import numpy as np
import math

def r_1(x):
    return 1 - x

def R_1(y_orig, y_new):
    if not math.isfinite(y_orig) or not math.isfinite(y_new):
        return False
    return math.isclose(y_new, 15.0 - y_orig, rel_tol=1e-12)

